import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import { countryName, flag, t } from './api';
import { fof, hasFofWidgets, placed } from '../common/fofWidgets';

/**
 * "Where we are": how many members are on the map, in how many countries,
 * the top few, and a way in. Counts only, from /api/member-map-stats/map (one
 * grouped query, cached ten minutes on the server), fetched once per page
 * load and shared by every place the widget is shown.
 */

const EXT = 'ernestdefoe-member-map';
const KEY = 'whereWeAre';
const store = {
  stats: null,
  loading: false
};
function load() {
  if (store.stats || store.loading || !app.forum.attribute('memberMapCanView')) return;
  store.loading = true;
  app.request({
    method: 'GET',
    url: app.forum.attribute('apiUrl') + '/member-map-stats/map',
    errorHandler: stayHidden
  }).then(document => store.stats = document.data.attributes).finally(() => {
    store.loading = false;
    m.redraw();
  });
}

/**
 * The widget sits on pages that aren't the map: if its counts can't load it
 * just doesn't show, rather than raise an alert about something nobody asked for.
 */
function stayHidden() {
  store.stats = null;
}
export function hasContent() {
  return !!app.forum.attribute('memberMapCanView') && (!store.stats || store.stats.members > 0);
}
export const WhereWeAre = {
  oninit: load,
  view(vnode) {
    const stats = store.stats;
    if (!app.forum.attribute('memberMapCanView') || !stats || !stats.members) return null;
    return m("div", {
      className: "MemberMapWidget"
    }, vnode.attrs.heading !== false && m("h4", {
      className: "MemberMapWidget-title"
    }, t('widget.title')), m("p", {
      className: "MemberMapWidget-line"
    }, t('widget.line', {
      members: stats.members,
      countries: stats.countries.length
    })), m("ul", {
      className: "MemberMapWidget-list"
    }, stats.countries.slice(0, 5).map(([cc, count]) => m("li", null, m("span", {
      "aria-hidden": "true"
    }, flag(cc)), " ", m("span", {
      className: "MemberMapWidget-country"
    }, countryName(cc)), ' ', m("span", {
      className: "MemberMapWidget-count"
    }, count)))), m(Link, {
      href: app.route('member-map'),
      className: "MemberMapWidget-open"
    }, t('widget.open')));
  }
};

/** Offer the widget to every host that is installed: Bespoke, Page Builder, fof/forum-widgets-core. */
export function registerWidgetHosts() {
  const extensions = globalThis.flarum?.extensions || {};
  if ('ernestdefoe-bespoke' in extensions) addToBespoke();
  if ('ernestdefoe-page-builder' in extensions) addToPageBuilder();
  if (hasFofWidgets()) addToFofWidgets();
}
function addToBespoke() {
  const g = globalThis;
  g.BespokeWidgetQueue = g.BespokeWidgetQueue || [];
  g.BespokeWidgetQueue.push({
    type: 'member-map-where-we-are',
    label: `${EXT}.forum.widget.title`,
    icon: 'fas fa-earth-americas',
    zones: ['sidebar', 'above-list', 'below-list', 'footer'],
    schema: [],
    component: {
      view: () => m(WhereWeAre)
    }
  });
}
function addToPageBuilder() {
  const g = globalThis;
  g.PageBuilderBlockQueue = g.PageBuilderBlockQueue || [];
  g.PageBuilderBlockQueue.push({
    type: 'member-map-where-we-are',
    component: {
      view: () => m(WhereWeAre)
    }
  });
}
function addToFofWidgets() {
  const Widgets = fof('common/extend/Widgets');
  const WidgetBase = fof('common/components/Widget');
  if (!Widgets || !WidgetBase || !app.widgets) return;
  class WhereWeAreWidget extends WidgetBase {
    className() {
      return 'MemberMapFofWidget';
    }
    icon() {
      return 'fas fa-earth-americas';
    }
    title() {
      return t('widget.title');
    }
    content() {
      return m(WhereWeAre, {
        heading: false
      });
    }
  }
  new Widgets().add({
    key: KEY,
    component: WhereWeAreWidget,
    isDisabled: () => !placed(app, EXT, KEY) || !hasContent(),
    isUnique: true,
    placement: 'end',
    position: 1
  }).extend(app, EXT);
}